python - << 'EOF'
from rdkit import Chem
m = Chem.MolFromMolFile('work/mol2d.mol', removeHs=False)
for a in m.GetAtoms():
    if a.GetChiralTag() != Chem.ChiralType.CHI_UNSPECIFIED:
        print('chiral', a.GetIdx(), a.GetSymbol(), a.GetChiralTag())
for b in m.GetBonds():
    if b.GetBondDir() != Chem.BondDir.NONE:
        print('wedge bond', b.GetBeginAtomIdx(), b.GetEndAtomIdx(), b.GetBondDir())
m2 = Chem.RemoveHs(m)
Chem.AssignStereochemistry(m2, cleanIt=True, force=True)
for a in m2.GetAtoms():
    if a.GetChiralTag() != Chem.ChiralType.CHI_UNSPECIFIED:
        print('after removeHs:', a.GetIdx(), a.GetSymbol(), a.GetChiralTag(), a.GetPropsAsDict().get('_CIPCode',''))
print(Chem.MolToSmiles(m2))
EOF

